"""Deterministic literature helpers for mathematical-modeling projects.

This module deliberately performs no network calls. Search services are selected by
the caller and their returned metadata is treated as untrusted input. The commands
create reproducible search plans, normalize DOI/BibTeX records, and check whether
manuscript claims are bound to verified evidence records.

Examples:
    python literature_tools.py plan --tasks tasks.json --output search-plan.json
    python literature_tools.py normalize --input candidates.json --output references.json
    python literature_tools.py normalize --bibtex-file references.bib --output references.json
    python literature_tools.py ledger --ledger claims.json --references references.json
    python literature_tools.py --self-test
"""

from __future__ import annotations

import argparse
import json
import re
import unicodedata
from collections import defaultdict
from pathlib import Path
from typing import Any, Iterable


DOI_RE = re.compile(r"^10\.\d{4,9}/\S+$", re.IGNORECASE)
YEAR_RE = re.compile(r"\b(18|19|20)\d{2}\b")
RESERVED_BIB = re.compile(r"[\\{}$%&#_~^]")


def _read_json(path: str | Path) -> Any:
    return json.loads(Path(path).read_text(encoding="utf-8"))


def _write_json(path: str | Path, value: Any) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def _as_list(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        return [part.strip() for part in re.split(r"[;,|]", value) if part.strip()]
    return [str(part).strip() for part in value if str(part).strip()]


def normalize_doi(value: Any) -> str | None:
    """Return a canonical DOI or ``None`` for missing/invalid values."""
    if value is None:
        return None
    doi = str(value).strip()
    doi = re.sub(r"^doi\s*:\s*", "", doi, flags=re.IGNORECASE)
    doi = re.sub(r"^https?://(?:dx\.)?doi\.org/", "", doi, flags=re.IGNORECASE)
    doi = doi.strip().rstrip(".,;:)]}>")
    # DOI syntax contains no whitespace; reject wrapped or concatenated input
    # instead of silently creating a different identifier.
    if re.search(r"\s", doi):
        return None
    doi = doi.casefold()
    return doi if DOI_RE.fullmatch(doi) else None


def normalize_title(value: Any) -> str:
    text = unicodedata.normalize("NFKD", str(value or "")).casefold()
    text = "".join(char for char in text if not unicodedata.combining(char))
    text = re.sub(r"[^\w\s]", " ", text, flags=re.UNICODE)
    return re.sub(r"\s+", " ", text).strip()


def _safe_year(value: Any) -> int | None:
    match = YEAR_RE.search(str(value or ""))
    return int(match.group(0)) if match else None


def _first_author(authors: Iterable[str]) -> str:
    first = next(iter(authors), "")
    # BibTeX supports "Family, Given" and ordinary "Given Family" forms.
    if "," in first:
        return first.split(",", 1)[0].strip()
    words = first.split()
    return words[-1] if words else ""


def _authors(value: Any) -> list[str]:
    """Parse BibTeX's ``and`` separator without splitting family/given commas."""
    if value is None:
        return []
    if isinstance(value, str):
        return [part.strip() for part in re.split(r"\s+and\s+", value, flags=re.IGNORECASE) if part.strip()]
    return [str(part).strip() for part in value if str(part).strip()]


def _bib_escape(value: str) -> str:
    return RESERVED_BIB.sub(lambda match: "\\" + match.group(0), value)


def parse_bibtex(text: str) -> list[dict[str, Any]]:
    """Parse common BibTeX entries without evaluating macros or embedded code."""
    records: list[dict[str, Any]] = []
    cursor = 0
    while True:
        match = re.search(r"@([A-Za-z]+)\s*([({])", text[cursor:])
        if not match:
            break
        start = cursor + match.start()
        opening = match.group(2)
        closing = "}" if opening == "{" else ")"
        body_start = cursor + match.end()
        depth = 1
        quote = False
        end = body_start
        while end < len(text) and depth:
            char = text[end]
            if char == '"' and (end == 0 or text[end - 1] != "\\"):
                quote = not quote
            elif not quote and char == opening:
                depth += 1
            elif not quote and char == closing:
                depth -= 1
            end += 1
        if depth:
            raise ValueError(f"unterminated BibTeX entry near offset {start}")
        body = text[body_start : end - 1].strip()
        comma = body.find(",")
        if comma < 0:
            cursor = end
            continue
        key = body[:comma].strip()
        fields: dict[str, str] = {"citation_key": key, "type": match.group(1).casefold()}
        for field, raw in _split_bib_fields(body[comma + 1 :]):
            fields[field.casefold()] = _strip_bib_value(raw)
        records.append(fields)
        cursor = end
    return records


def _split_bib_fields(body: str) -> list[tuple[str, str]]:
    result: list[tuple[str, str]] = []
    start = 0
    depth = 0
    quote = False
    chunks: list[str] = []
    for index, char in enumerate(body):
        if char == '"' and (index == 0 or body[index - 1] != "\\"):
            quote = not quote
        elif not quote and char == "{":
            depth += 1
        elif not quote and char == "}" and depth:
            depth -= 1
        elif not quote and depth == 0 and char == ",":
            chunks.append(body[start:index])
            start = index + 1
    chunks.append(body[start:])
    for chunk in chunks:
        if "=" not in chunk:
            continue
        name, value = chunk.split("=", 1)
        if name.strip():
            result.append((name.strip(), value.strip()))
    return result


def _strip_bib_value(value: str) -> str:
    value = value.strip()
    if len(value) >= 2 and ((value[0] == value[-1] == '"') or (value[0] == "{" and value[-1] == "}")):
        value = value[1:-1]
    return re.sub(r"\s+", " ", value.replace("\\&", "&")).strip()


def _canonical_record(raw: dict[str, Any], index: int) -> dict[str, Any]:
    authors = _authors(raw.get("authors", raw.get("author")))
    title = str(raw.get("title", "")).strip()
    record: dict[str, Any] = {
        "id": str(raw.get("id") or raw.get("citation_key") or f"candidate-{index + 1}"),
        "status": str(raw.get("status", "candidate")).casefold(),
        "role": str(raw.get("role", "background")).strip(),
        "title": title,
        "authors": authors,
        "year": _safe_year(raw.get("year")),
        "venue": str(raw.get("venue", raw.get("journal", raw.get("booktitle", "")))).strip(),
        "doi": normalize_doi(raw.get("doi")),
        "url": str(raw.get("url", "")).strip() or None,
        "citation_key": str(raw.get("citation_key", "")).strip() or None,
    }
    for key in ("claim_supported", "scope", "limitations", "verification"):
        if key in raw:
            record[key] = raw[key]
    return record


def _merge_records(records: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[list[str]]]:
    groups: dict[tuple[str, str], list[dict[str, Any]]] = defaultdict(list)
    for record in records:
        identity = ("doi", record["doi"]) if record.get("doi") else (
            "title", f"{normalize_title(record.get('title'))}|{record.get('year') or ''}|{normalize_title(_first_author(record.get('authors', [])))}"
        )
        groups[identity].append(record)
    merged: list[dict[str, Any]] = []
    duplicate_groups: list[list[str]] = []
    for members in groups.values():
        status_rank = {"verified": 0, "screened": 1, "candidate": 2, "rejected": 3}
        ordered = sorted(members, key=lambda item: (status_rank.get(str(item.get("status", "candidate")).casefold(), 4), -sum(value not in (None, "", []) for value in item.values()), item["id"]))
        winner = dict(ordered[0])
        for candidate in ordered[1:]:
            for key, value in candidate.items():
                if winner.get(key) in (None, "", []) and value not in (None, "", []):
                    winner[key] = value
        merged.append(winner)
        if len(members) > 1:
            duplicate_groups.append([member["id"] for member in members])
    # Stable keys avoid changing a manuscript when input order changes.
    used: dict[str, int] = {}
    for record in sorted(merged, key=lambda item: (normalize_title(item.get("title")), item.get("year") or 0, item["id"])):
        base = re.sub(r"[^a-z0-9]+", "", _first_author(record.get("authors", [])).casefold()) or "source"
        base += str(record.get("year") or "nd")
        title_token = next(iter(normalize_title(record.get("title")).split()), "source")
        base += re.sub(r"[^a-z0-9]+", "", title_token)[:12]
        used[base] = used.get(base, 0) + 1
        record["citation_key"] = base if used[base] == 1 else f"{base}{used[base]}"
    return sorted(merged, key=lambda item: item["citation_key"]), duplicate_groups


def normalize_records(records: list[dict[str, Any]]) -> dict[str, Any]:
    canonical = [_canonical_record(record, index) for index, record in enumerate(records)]
    normalized, duplicate_groups = _merge_records(canonical)
    issues: list[dict[str, Any]] = []
    for record in normalized:
        missing = [field for field in ("title", "authors", "year") if not record.get(field)]
        if missing:
            issues.append({"id": record["id"], "kind": "missing_field", "fields": missing})
        if record.get("doi") is None and not record.get("url"):
            issues.append({"id": record["id"], "kind": "missing_identifier", "message": "no valid DOI or URL"})
    return {"version": 1, "records": normalized, "duplicate_groups": duplicate_groups, "issues": issues}


def build_search_plan(tasks: list[dict[str, Any]], *, databases: list[str], languages: list[str], start_year: int | None, end_year: int | None) -> dict[str, Any]:
    facets = ("phenomenon", "domain", "task", "method", "population", "validation")
    plan_tasks = []
    for index, task in enumerate(tasks):
        values = {key: _as_list(task.get(key)) for key in facets}
        domain_terms = values["domain"] or values["phenomenon"] or ["mathematical modeling"]
        task_terms = values["task"] or ["modeling"]
        method_terms = values["method"] or ["method comparison"]
        validation_terms = values["validation"] or ["validation"]
        broad = f"({' OR '.join(domain_terms)}) AND ({' OR '.join(task_terms)}) AND ({' OR '.join(method_terms)})"
        precise = broad + f" AND ({' OR '.join(validation_terms)})"
        plan_tasks.append({
            "id": str(task.get("id") or f"task-{index + 1}"),
            "facets": values,
            "queries": [{"purpose": "discovery", "query": broad}, {"purpose": "verification", "query": precise}],
            "screening": {"include": ["directly addresses the task or method", "reports enough metadata to verify", "matches the population or setting"], "exclude": ["snippet-only records", "unverifiable identifiers", "duplicate or retracted records"]},
        })
    return {
        "version": 1,
        "boundary": {"databases": databases, "languages": languages, "year_range": [start_year, end_year], "document_types": ["journal article", "conference paper", "review", "standard"], "stopping_rule": "stop after each task has verified method provenance and domain evidence, or record a boundary failure"},
        "tasks": plan_tasks,
        "logging_fields": ["timestamp", "service", "exact_query", "filters", "result_count", "screened_count", "decision", "reason"],
        "notes": ["A negative result means not found inside this boundary; it does not prove absence.", "Do not infer a DOI from a title pattern; verify metadata against a registry or publisher."],
    }


def validate_ledger(claims: list[dict[str, Any]], references: list[dict[str, Any]]) -> dict[str, Any]:
    by_id = {str(reference.get("id")): reference for reference in references}
    errors: list[dict[str, Any]] = []
    warnings: list[dict[str, Any]] = []
    if len(by_id) != len(references):
        errors.append({"kind": "duplicate_reference_id"})
    for claim in claims:
        claim_id = str(claim.get("claim_id") or claim.get("id") or "<missing>")
        evidence_ids = _as_list(claim.get("evidence_ids", claim.get("sources", [])))
        if not str(claim.get("text", "")).strip():
            errors.append({"claim_id": claim_id, "kind": "empty_claim"})
        if not evidence_ids:
            errors.append({"claim_id": claim_id, "kind": "unsupported_claim"})
        if len(set(evidence_ids)) != len(evidence_ids):
            errors.append({"claim_id": claim_id, "kind": "duplicate_evidence_binding"})
        for evidence_id in evidence_ids:
            reference = by_id.get(evidence_id)
            if reference is None:
                errors.append({"claim_id": claim_id, "evidence_id": evidence_id, "kind": "unknown_evidence"})
                continue
            if str(reference.get("status", "")).casefold() != "verified":
                errors.append({"claim_id": claim_id, "evidence_id": evidence_id, "kind": "unverified_evidence"})
            if not str(reference.get("claim_supported", "")).strip():
                errors.append({"claim_id": claim_id, "evidence_id": evidence_id, "kind": "missing_supported_proposition"})
            if not str(reference.get("scope", "")).strip():
                warnings.append({"claim_id": claim_id, "evidence_id": evidence_id, "kind": "missing_source_scope"})
        strength = str(claim.get("strength", "")).casefold()
        if any(token in str(claim.get("text", "")).casefold() for token in ("always", "never", "proves", "causes", "all")) and strength not in {"descriptive", "bounded"}:
            warnings.append({"claim_id": claim_id, "kind": "overclaim_language", "message": "replace universal/causal wording with a bounded proposition or document causal design"})
    return {"version": 1, "valid": not errors, "claim_count": len(claims), "reference_count": len(references), "errors": errors, "warnings": warnings}


def _self_test() -> dict[str, Any]:
    assert normalize_doi("10.1234/has whitespace") is None
    bib = '@article{Smith2022, author = {Smith, Ada and Doe, Lin}, title = {A Robust Method}, year = {2022}, doi = {https://doi.org/10.1234/ABC.1}, journal = {Journal}}'
    parsed = parse_bibtex(bib)
    normalized = normalize_records(parsed + [{"id": "copy", "title": "A Robust Method", "authors": ["Ada Smith", "Lin Doe"], "year": 2022, "doi": "10.1234/abc.1", "status": "verified", "claim_supported": "bounded method result", "scope": "benchmark"}])
    assert len(normalized["records"]) == 1 and normalized["duplicate_groups"]
    plan = build_search_plan([{"id": "forecast", "domain": ["rainfall"], "task": ["forecasting"], "method": ["ARIMA"]}], databases=["Crossref"], languages=["en"], start_year=2015, end_year=2026)
    assert "verification" in plan["tasks"][0]["queries"][1]["purpose"]
    reference = dict(normalized["records"][0]); reference.update({"id": "lit-001", "status": "verified", "claim_supported": "bounded method result", "scope": "benchmark"})
    ledger = validate_ledger([{"claim_id": "c1", "text": "The method improves error on this benchmark.", "evidence_ids": ["lit-001"], "strength": "bounded"}], [reference])
    assert ledger["valid"]
    invalid_ledger = validate_ledger([{"claim_id": "bad", "text": "The method always causes improvement.", "evidence_ids": ["missing"]}], [])
    assert not invalid_ledger["valid"] and invalid_ledger["errors"]
    return {"parsed": parsed, "normalized": normalized, "plan": plan, "ledger": ledger, "invalid_ledger": invalid_ledger}


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--self-test", action="store_true")
    parser.add_argument("--self-test-output", type=Path)
    sub = parser.add_subparsers(dest="command")
    plan = sub.add_parser("plan", help="build a reproducible search boundary and query plan")
    plan.add_argument("--tasks", required=True, help="JSON list or object containing tasks")
    plan.add_argument("--output", required=True)
    plan.add_argument("--databases", default="Crossref,OpenAlex,Google Scholar")
    plan.add_argument("--languages", default="en")
    plan.add_argument("--start-year", type=int)
    plan.add_argument("--end-year", type=int)
    normalize = sub.add_parser("normalize", help="normalize and deduplicate JSON or BibTeX records")
    normalize.add_argument("--input")
    normalize.add_argument("--bibtex-file")
    normalize.add_argument("--output", required=True)
    ledger = sub.add_parser("ledger", help="validate claim-to-source bindings")
    ledger.add_argument("--ledger", required=True)
    ledger.add_argument("--references", required=True)
    ledger.add_argument("--output")
    return parser


def main(argv: list[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    if args.self_test:
        report = _self_test()
        if args.self_test_output:
            _write_json(args.self_test_output, report)
        else:
            print(json.dumps(report, ensure_ascii=False, indent=2))
        return 0
    if args.command == "plan":
        payload = _read_json(args.tasks)
        tasks = payload.get("tasks", payload) if isinstance(payload, dict) else payload
        _write_json(args.output, build_search_plan(tasks, databases=_as_list(args.databases), languages=_as_list(args.languages), start_year=args.start_year, end_year=args.end_year))
        return 0
    if args.command == "normalize":
        if bool(args.input) == bool(args.bibtex_file):
            raise SystemExit("choose exactly one of --input or --bibtex-file")
        records = parse_bibtex(Path(args.bibtex_file).read_text(encoding="utf-8")) if args.bibtex_file else _read_json(args.input)
        if isinstance(records, dict):
            records = records.get("records", records.get("references", []))
        _write_json(args.output, normalize_records(records))
        return 0
    if args.command == "ledger":
        claims_payload = _read_json(args.ledger)
        refs_payload = _read_json(args.references)
        claims = claims_payload.get("claims", claims_payload) if isinstance(claims_payload, dict) else claims_payload
        references = refs_payload.get("records", refs_payload.get("references", refs_payload)) if isinstance(refs_payload, dict) else refs_payload
        result = validate_ledger(claims, references)
        if args.output:
            _write_json(args.output, result)
        else:
            print(json.dumps(result, ensure_ascii=False, indent=2))
        return 0 if result["valid"] else 2
    _parser().print_help()
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

"""Small numerical recipes with explicit validation outputs.

These functions are templates, not a universal solver. Adapt the data interface and
persist their returned diagnostics in each subproblem result contract.
"""

from __future__ import annotations

import argparse
import heapq
import json
import math
from pathlib import Path

import numpy as np


def regression_metrics(actual, predicted):
    actual = np.asarray(actual, dtype=float)
    predicted = np.asarray(predicted, dtype=float)
    if actual.shape != predicted.shape or actual.size == 0:
        raise ValueError("actual and predicted must be nonempty and shape-compatible")
    residual = predicted - actual
    mae = float(np.mean(np.abs(residual)))
    rmse = float(np.sqrt(np.mean(residual**2)))
    denominator = float(np.sum((actual - np.mean(actual)) ** 2))
    r2 = float(1 - np.sum(residual**2) / denominator) if denominator > 0 else None
    return {"mae": mae, "rmse": rmse, "r2": r2, "bias": float(np.mean(residual))}


def ols_fit(features, target, add_intercept=True):
    matrix = np.asarray(features, dtype=float)
    response = np.asarray(target, dtype=float)
    if matrix.ndim == 1:
        matrix = matrix[:, None]
    if matrix.ndim != 2 or response.ndim != 1 or matrix.shape[0] != response.size or response.size < 2:
        raise ValueError("features and target must define compatible observations")
    if not np.isfinite(matrix).all() or not np.isfinite(response).all():
        raise ValueError("OLS inputs must be finite")
    design = np.column_stack([np.ones(response.size), matrix]) if add_intercept else matrix
    coefficients, _, rank, singular = np.linalg.lstsq(design, response, rcond=None)
    predictions = design @ coefficients
    return {
        "coefficients": coefficients.tolist(),
        "add_intercept": bool(add_intercept),
        "rank": int(rank),
        "condition_number": float(np.linalg.cond(design)),
        "singular_values": singular.tolist(),
        "predicted": predictions.tolist(),
        "metrics": regression_metrics(response, predictions),
    }


def ahp_weights(pairwise, consistency_threshold=0.1, reciprocity_tolerance=1e-6):
    matrix = np.asarray(pairwise, dtype=float)
    if matrix.ndim != 2 or matrix.shape[0] != matrix.shape[1] or matrix.shape[0] < 2:
        raise ValueError("AHP pairwise matrix must be square with at least two criteria")
    if not np.isfinite(matrix).all() or np.any(matrix <= 0):
        raise ValueError("AHP comparisons must be positive and finite")
    reciprocity_error = float(np.max(np.abs(matrix * matrix.T - 1)))
    diagonal_error = float(np.max(np.abs(np.diag(matrix) - 1)))
    eigenvalues, eigenvectors = np.linalg.eig(matrix)
    dominant_index = int(np.argmax(eigenvalues.real))
    dominant = float(eigenvalues[dominant_index].real)
    vector = np.abs(eigenvectors[:, dominant_index].real)
    weights = vector / vector.sum()
    size = matrix.shape[0]
    consistency_index = max((dominant - size) / (size - 1), 0.0)
    random_index = {1: 0.0, 2: 0.0, 3: 0.58, 4: 0.90, 5: 1.12, 6: 1.24,
                    7: 1.32, 8: 1.41, 9: 1.45, 10: 1.49}.get(size)
    consistency_ratio = consistency_index / random_index if random_index else 0.0 if size <= 2 else None
    accepted = reciprocity_error <= reciprocity_tolerance and diagonal_error <= reciprocity_tolerance
    if consistency_ratio is not None:
        accepted = accepted and consistency_ratio < consistency_threshold
    return {
        "weights": weights.tolist(),
        "lambda_max": dominant,
        "consistency_index": consistency_index,
        "consistency_ratio": consistency_ratio,
        "consistency_threshold": consistency_threshold,
        "reciprocity_error": reciprocity_error,
        "accepted": bool(accepted),
    }


def gm11_forecast(series, forecast_steps=1):
    values = np.asarray(series, dtype=float)
    if values.ndim != 1 or values.size < 4 or not np.isfinite(values).all() or np.any(values <= 0):
        raise ValueError("GM(1,1) requires at least four positive finite observations")
    if int(forecast_steps) < 0:
        raise ValueError("forecast_steps must be nonnegative")
    accumulated = np.cumsum(values)
    background = -0.5 * (accumulated[1:] + accumulated[:-1])
    design = np.column_stack([background, np.ones(values.size - 1)])
    development, input_term = np.linalg.lstsq(design, values[1:], rcond=None)[0]
    if abs(development) < 1e-12:
        raise ValueError("GM(1,1) development coefficient is numerically zero")
    total = values.size + int(forecast_steps)
    accumulated_hat = np.asarray([
        (values[0] - input_term / development) * math.exp(-development * index)
        + input_term / development
        for index in range(total)
    ])
    restored = np.concatenate([[values[0]], np.diff(accumulated_hat)])
    fitted = restored[:values.size]
    ratios = values[:-1] / values[1:]
    lower = math.exp(-2 / (values.size + 1))
    upper = math.exp(2 / (values.size + 1))
    return {
        "development_coefficient": float(development),
        "input_term": float(input_term),
        "fitted": fitted.tolist(),
        "forecast": restored[values.size:].tolist(),
        "metrics": regression_metrics(values, fitted),
        "level_ratio_bounds": [lower, upper],
        "level_ratio_admissible": bool(np.all((ratios > lower) & (ratios < upper))),
    }


def deterministic_kmeans(features, clusters, max_iterations=100, tolerance=1e-8):
    data = np.asarray(features, dtype=float)
    count = int(clusters)
    if data.ndim != 2 or data.shape[0] < count or count < 2 or not np.isfinite(data).all():
        raise ValueError("k-means requires a finite two-dimensional matrix and 2 <= clusters <= rows")
    if np.unique(data, axis=0).shape[0] < count:
        raise ValueError("clusters cannot exceed the number of unique rows")
    mean = data.mean(axis=0)
    centers = [data[int(np.argmin(np.sum((data - mean) ** 2, axis=1)))]]
    while len(centers) < count:
        distances = np.min(np.stack([np.sum((data - center) ** 2, axis=1) for center in centers]), axis=0)
        centers.append(data[int(np.argmax(distances))])
    centers = np.asarray(centers, dtype=float)
    iterations = 0
    for iterations in range(1, int(max_iterations) + 1):
        squared = np.stack([np.sum((data - center) ** 2, axis=1) for center in centers], axis=1)
        labels = np.argmin(squared, axis=1)
        updated = np.asarray([data[labels == index].mean(axis=0) for index in range(count)])
        shift = float(np.max(np.linalg.norm(updated - centers, axis=1)))
        centers = updated
        if shift <= tolerance:
            break
    squared = np.stack([np.sum((data - center) ** 2, axis=1) for center in centers], axis=1)
    labels = np.argmin(squared, axis=1)
    return {
        "centers": centers.tolist(),
        "labels": labels.tolist(),
        "cluster_sizes": [int(np.sum(labels == index)) for index in range(count)],
        "inertia": float(np.sum(squared[np.arange(data.shape[0]), labels])),
        "iterations": iterations,
        "converged": iterations < int(max_iterations),
    }


def split_indices(strategy, length=None, test_fraction=0.2, seed=2025, groups=None,
                  time_values=None, coordinates=None, block_size=None):
    if not 0 < float(test_fraction) < 1:
        raise ValueError("test_fraction must lie between zero and one")
    rng = np.random.default_rng(int(seed))
    strategy = str(strategy).lower()
    if strategy == "iid":
        size = int(length or 0)
        order = np.arange(size)
        rng.shuffle(order)
        test_count = max(1, min(size - 1, int(math.ceil(size * test_fraction))))
        test = sorted(order[:test_count].tolist())
    elif strategy in {"group", "spatial"}:
        if strategy == "group":
            memberships = list(groups or [])
        else:
            if not coordinates or not block_size or float(block_size) <= 0:
                raise ValueError("spatial split requires coordinates and positive block_size")
            memberships = [
                (math.floor(float(point[0]) / float(block_size)), math.floor(float(point[1]) / float(block_size)))
                for point in coordinates
            ]
        size = len(memberships)
        unique = sorted(set(memberships), key=repr)
        if len(unique) < 2:
            raise ValueError("grouped split requires at least two distinct groups or blocks")
        rng.shuffle(unique)
        group_count = max(1, min(len(unique) - 1, int(math.ceil(len(unique) * test_fraction))))
        selected = set(unique[:group_count])
        test = [index for index, membership in enumerate(memberships) if membership in selected]
    elif strategy == "time":
        values = list(time_values or [])
        size = len(values)
        if size < 2:
            raise ValueError("time split requires at least two ordered values")
        order = sorted(range(size), key=lambda index: values[index])
        test_count = max(1, min(size - 1, int(math.ceil(size * test_fraction))))
        test = sorted(order[-test_count:])
    else:
        raise ValueError("strategy must be iid, group, time, or spatial")
    if size < 2 or not test or len(test) >= size:
        raise ValueError("split must leave nonempty train and test sets")
    test_set = set(test)
    train = [index for index in range(size) if index not in test_set]
    audit = {"index_overlap": bool(set(train) & test_set), "train_rows": len(train), "test_rows": len(test)}
    if strategy in {"group", "spatial"}:
        audit["group_overlap"] = bool({memberships[index] for index in train} & {memberships[index] for index in test})
    return {"strategy": strategy, "seed": int(seed), "train_indices": train, "test_indices": test, "audit": audit}


def shortest_path(edges, source, target, directed=False):
    graph = {}
    for edge in edges:
        if len(edge) != 3:
            raise ValueError("each edge must contain source, target, and weight")
        left, right, weight = edge
        weight = float(weight)
        if not math.isfinite(weight) or weight < 0:
            raise ValueError("Dijkstra recipe requires finite nonnegative weights")
        graph.setdefault(str(left), []).append((str(right), weight))
        graph.setdefault(str(right), [])
        if not directed:
            graph[str(right)].append((str(left), weight))
    source, target = str(source), str(target)
    if source not in graph or target not in graph:
        raise ValueError("source and target must occur in the graph")
    distances = {source: 0.0}
    previous = {}
    queue = [(0.0, source)]
    while queue:
        distance, node = heapq.heappop(queue)
        if distance != distances.get(node):
            continue
        if node == target:
            break
        for neighbor, weight in graph[node]:
            candidate = distance + weight
            if candidate < distances.get(neighbor, math.inf):
                distances[neighbor] = candidate
                previous[neighbor] = node
                heapq.heappush(queue, (candidate, neighbor))
    if target not in distances:
        return {"reachable": False, "distance": None, "path": []}
    path = [target]
    while path[-1] != source:
        path.append(previous[path[-1]])
    return {"reachable": True, "distance": distances[target], "path": list(reversed(path))}


def binary_linear_program(objective, constraints, maximize=False, tolerance=1e-9):
    coefficients = np.asarray(objective, dtype=float)
    if coefficients.ndim != 1 or coefficients.size < 1 or coefficients.size > 20:
        raise ValueError("binary exact baseline supports between one and twenty variables")
    if not np.isfinite(coefficients).all():
        raise ValueError("objective coefficients must be finite")
    normalized = []
    for constraint in constraints:
        lhs = np.asarray(constraint["coefficients"], dtype=float)
        sense = constraint["sense"]
        rhs = float(constraint["rhs"])
        if lhs.shape != coefficients.shape or sense not in {"<=", ">=", "=="} or not np.isfinite(lhs).all() or not math.isfinite(rhs):
            raise ValueError("invalid binary linear constraint")
        normalized.append((lhs, sense, rhs))
    best_value = -math.inf if maximize else math.inf
    best = None
    feasible_count = 0
    for mask in range(1 << coefficients.size):
        decision = np.asarray([(mask >> index) & 1 for index in range(coefficients.size)], dtype=float)
        feasible = True
        for lhs, sense, rhs in normalized:
            value = float(lhs @ decision)
            if sense == "<=" and value > rhs + tolerance:
                feasible = False
            elif sense == ">=" and value < rhs - tolerance:
                feasible = False
            elif sense == "==" and abs(value - rhs) > tolerance:
                feasible = False
            if not feasible:
                break
        if not feasible:
            continue
        feasible_count += 1
        value = float(coefficients @ decision)
        if best is None or (maximize and value > best_value + tolerance) or (not maximize and value < best_value - tolerance):
            best_value, best = value, decision.astype(int).tolist()
    if best is None:
        return {"status": "infeasible", "decision": None, "objective_value": None,
                "assignments_checked": 1 << coefficients.size, "feasible_assignments": 0}
    return {
        "status": "optimal",
        "sense": "max" if maximize else "min",
        "decision": best,
        "objective_value": best_value,
        "assignments_checked": 1 << coefficients.size,
        "feasible_assignments": feasible_count,
        "optimality_gap": 0.0,
    }


def rolling_origins(length, minimum_train, horizon, step=1):
    if minimum_train < 2 or horizon < 1 or step < 1:
        raise ValueError("invalid rolling-origin configuration")
    return [
        {"train": [0, origin], "test": [origin, origin + horizon]}
        for origin in range(minimum_train, length - horizon + 1, step)
    ]


def entropy_topsis(matrix, directions):
    data = np.asarray(matrix, dtype=float)
    if data.ndim != 2 or data.shape[0] < 2 or data.shape[1] != len(directions):
        raise ValueError("matrix/direction mismatch")
    oriented = np.empty_like(data)
    for column, direction in enumerate(directions):
        values = data[:, column]
        spread = float(np.max(values) - np.min(values))
        if spread == 0:
            oriented[:, column] = 0.0
        elif direction == "benefit":
            oriented[:, column] = (values - np.min(values)) / spread
        elif direction == "cost":
            oriented[:, column] = (np.max(values) - values) / spread
        else:
            raise ValueError("direction must be benefit or cost")
    shifted = oriented + 1e-12
    proportions = shifted / shifted.sum(axis=0)
    entropy = -(proportions * np.log(proportions)).sum(axis=0) / math.log(data.shape[0])
    diversity = 1 - entropy
    weights = diversity / diversity.sum() if diversity.sum() > 0 else np.full(data.shape[1], 1 / data.shape[1])
    weighted = oriented * weights
    positive = weighted.max(axis=0)
    negative = weighted.min(axis=0)
    d_positive = np.linalg.norm(weighted - positive, axis=1)
    d_negative = np.linalg.norm(weighted - negative, axis=1)
    closeness = d_negative / np.maximum(d_positive + d_negative, 1e-15)
    return {
        "weights": weights.tolist(),
        "closeness": closeness.tolist(),
        "rank_order": np.argsort(-closeness).tolist(),
        "normalized": oriented.tolist(),
    }


def constraint_report(values, lower=None, upper=None, equality=None, tolerance=1e-7):
    values = np.asarray(values, dtype=float)
    violations = []
    if lower is not None:
        lower = np.asarray(lower, dtype=float)
        violations.extend(np.maximum(lower - values, 0).ravel())
    if upper is not None:
        upper = np.asarray(upper, dtype=float)
        violations.extend(np.maximum(values - upper, 0).ravel())
    if equality is not None:
        violations.extend(np.abs(np.asarray(equality, dtype=float)).ravel())
    maximum = float(max(violations, default=0.0))
    return {"feasible": maximum <= tolerance, "max_violation": maximum, "tolerance": tolerance}


def monte_carlo_summary(samples, confidence=0.95):
    values = np.asarray(samples, dtype=float)
    if values.ndim != 1 or values.size < 2 or not np.isfinite(values).all():
        raise ValueError("samples must contain at least two finite values")
    alpha = 1 - confidence
    standard_error = float(np.std(values, ddof=1) / math.sqrt(values.size))
    return {
        "draws": int(values.size),
        "mean": float(np.mean(values)),
        "standard_error": standard_error,
        "interval": np.quantile(values, [alpha / 2, 1 - alpha / 2]).tolist(),
        "q05_q50_q95": np.quantile(values, [0.05, 0.5, 0.95]).tolist(),
    }


def markov_diagnostics(transition, tolerance=1e-10):
    matrix = np.asarray(transition, dtype=float)
    if matrix.ndim != 2 or matrix.shape[0] != matrix.shape[1]:
        raise ValueError("transition matrix must be square")
    row_error = np.abs(matrix.sum(axis=1) - 1)
    return {
        "valid": bool(np.all(matrix >= -tolerance) and np.max(row_error) <= tolerance),
        "minimum_entry": float(matrix.min()),
        "maximum_row_sum_error": float(row_error.max()),
    }


def sensitivity_table(base_parameters, evaluator, relative_changes=(-0.2, -0.1, 0.1, 0.2)):
    base_parameters = dict(base_parameters)
    base_value = float(evaluator(base_parameters))
    rows = []
    for name, original in base_parameters.items():
        if not isinstance(original, (int, float)) or original == 0:
            continue
        for change in relative_changes:
            varied = dict(base_parameters)
            varied[name] = original * (1 + change)
            value = float(evaluator(varied))
            elasticity = ((value - base_value) / base_value) / change if base_value != 0 else None
            rows.append({"parameter": name, "relative_change": change, "value": value, "elasticity": elasticity})
    return {"base_value": base_value, "rows": rows}


def _self_test():
    report = {
        "regression": regression_metrics([1, 2, 3], [1.1, 1.9, 3.2]),
        "ols": ols_fit([[0], [1], [2]], [1, 3, 5]),
        "ahp": ahp_weights([[1, 2, 4], [0.5, 1, 2], [0.25, 0.5, 1]]),
        "gm11": gm11_forecast([10, 12, 15, 18, 22], 2),
        "clusters": deterministic_kmeans([[0, 0], [0, 1], [8, 8], [9, 8]], 2),
        "split": split_indices("group", groups=["a", "a", "b", "b"], test_fraction=0.5),
        "path": shortest_path([["a", "b", 1], ["b", "c", 2], ["a", "c", 5]], "a", "c"),
        "binary": binary_linear_program(
            [8, 6, 5], [{"coefficients": [4, 3, 2], "sense": "<=", "rhs": 6}], maximize=True,
        ),
        "origins": rolling_origins(20, 10, 2, 3),
        "ranking": entropy_topsis([[2, 5], [3, 4], [5, 2]], ["benefit", "cost"]),
        "constraints": constraint_report([1, 2], lower=[0, 0], upper=[2, 2]),
        "simulation": monte_carlo_summary([1, 2, 3, 4]),
        "markov": markov_diagnostics([[0.8, 0.2], [0.1, 0.9]]),
    }
    assert report["constraints"]["feasible"]
    assert report["markov"]["valid"]
    assert report["ahp"]["accepted"]
    assert report["path"]["distance"] == 3
    assert report["binary"]["objective_value"] == 13
    assert not report["split"]["audit"]["group_overlap"]
    print(json.dumps(report, indent=2))


def run_contract(contract):
    operation = contract.get("operation")
    if operation == "regression_metrics":
        return regression_metrics(contract["actual"], contract["predicted"])
    if operation == "ols_fit":
        return ols_fit(contract["features"], contract["target"], bool(contract.get("add_intercept", True)))
    if operation == "ahp_weights":
        return ahp_weights(
            contract["pairwise"], float(contract.get("consistency_threshold", 0.1)),
            float(contract.get("reciprocity_tolerance", 1e-6)),
        )
    if operation == "gm11_forecast":
        return gm11_forecast(contract["series"], int(contract.get("forecast_steps", 1)))
    if operation == "deterministic_kmeans":
        return deterministic_kmeans(
            contract["features"], int(contract["clusters"]),
            int(contract.get("max_iterations", 100)), float(contract.get("tolerance", 1e-8)),
        )
    if operation == "split_indices":
        return split_indices(
            contract["strategy"], contract.get("length"), float(contract.get("test_fraction", 0.2)),
            int(contract.get("seed", 2025)), contract.get("groups"), contract.get("time_values"),
            contract.get("coordinates"), contract.get("block_size"),
        )
    if operation == "shortest_path":
        return shortest_path(
            contract["edges"], contract["source"], contract["target"], bool(contract.get("directed", False)),
        )
    if operation == "binary_linear_program":
        return binary_linear_program(
            contract["objective"], contract.get("constraints", []), bool(contract.get("maximize", False)),
            float(contract.get("tolerance", 1e-9)),
        )
    if operation == "rolling_origins":
        return rolling_origins(
            int(contract["length"]), int(contract["minimum_train"]),
            int(contract["horizon"]), int(contract.get("step", 1)),
        )
    if operation == "entropy_topsis":
        return entropy_topsis(contract["matrix"], contract["directions"])
    if operation == "constraint_report":
        return constraint_report(
            contract["values"], contract.get("lower"), contract.get("upper"),
            contract.get("equality"), float(contract.get("tolerance", 1e-7)),
        )
    if operation == "monte_carlo_summary":
        return monte_carlo_summary(contract["samples"], float(contract.get("confidence", 0.95)))
    if operation == "markov_diagnostics":
        return markov_diagnostics(contract["transition"], float(contract.get("tolerance", 1e-10)))
    raise ValueError(f"unsupported operation: {operation}")


def main():
    parser = argparse.ArgumentParser(description="Run a deterministic modeling recipe from a JSON contract")
    parser.add_argument("--input", help="input JSON contract")
    parser.add_argument("--output", help="write result JSON")
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args()
    if args.self_test or not args.input:
        _self_test()
        return 0
    contract = json.loads(Path(args.input).read_text(encoding="utf-8"))
    payload = {
        "schema_version": 1,
        "operation": contract.get("operation"),
        "result": run_contract(contract),
    }
    rendered = json.dumps(payload, ensure_ascii=False, indent=2) + "\n"
    if args.output:
        target = Path(args.output)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(rendered, encoding="utf-8")
    else:
        print(rendered, end="")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Deterministic result checks for mathematical-modeling artifacts.

The module intentionally uses only the Python standard library.  It is a small
validator, not a solver: it reports evidence and a status so a workflow can
decide whether a claim is publishable.  Input/output are JSON for easy use from
the desktop runtime and for reproducible archived checks.
"""

from __future__ import annotations

import argparse
import json
import math
import statistics
from pathlib import Path
from typing import Any, Iterable, Sequence


EPS = 1e-12


def _finite(value: Any) -> bool:
    return isinstance(value, (int, float)) and math.isfinite(float(value))


def _numbers(values: Iterable[Any], name: str, minimum: int = 1) -> list[float]:
    result = [float(value) for value in values]
    if len(result) < minimum or not all(math.isfinite(value) for value in result):
        raise ValueError(f"{name} must contain at least {minimum} finite numbers")
    return result


def _mean(values: Sequence[float]) -> float:
    return statistics.fmean(values)


def _rmse(actual: Sequence[float], predicted: Sequence[float]) -> float:
    return math.sqrt(_mean([(a - p) ** 2 for a, p in zip(actual, predicted)]))


def _mae(actual: Sequence[float], predicted: Sequence[float]) -> float:
    return _mean([abs(a - p) for a, p in zip(actual, predicted)])


def _status(ok: bool, evidence: dict[str, Any], failures: list[str]) -> dict[str, Any]:
    return {
        "status": "passed" if ok else "failed",
        "ok": bool(ok),
        "failures": failures,
        "evidence": evidence,
    }


def rolling_origin_check(payload: dict[str, Any]) -> dict[str, Any]:
    """Check ordered holdouts against a last-observation baseline.

    ``predicted`` is indexed like ``actual``.  ``origins`` contains either
    ``{train_end, horizon}`` or explicit ``{train_end, test_start, test_end}``
    entries, with the end indices exclusive.  A supplied ``baseline`` may be
    indexed like actual; otherwise the previous observed value is repeated.
    """
    actual = _numbers(payload.get("actual", []), "actual", 4)
    predicted = _numbers(payload.get("predicted", []), "predicted", len(actual))
    if len(predicted) != len(actual):
        raise ValueError("actual and predicted must have the same length")
    raw_origins = payload.get("origins") or []
    if not raw_origins:
        minimum_train = int(payload.get("minimum_train", max(2, len(actual) // 2)))
        horizon = int(payload.get("horizon", 1))
        step = int(payload.get("step", 1))
        raw_origins = [
            {"train_end": i, "test_start": i, "test_end": i + horizon}
            for i in range(minimum_train, len(actual) - horizon + 1, step)
        ]
    baseline_input = payload.get("baseline")
    baseline = _numbers(baseline_input, "baseline", len(actual)) if baseline_input is not None else None
    if baseline is not None and len(baseline) != len(actual):
        raise ValueError("baseline must have the same length as actual")
    rows: list[dict[str, Any]] = []
    failures: list[str] = []
    for index, raw in enumerate(raw_origins):
        train_end = int(raw["train_end"])
        test_start = int(raw.get("test_start", train_end))
        test_end = int(raw.get("test_end", test_start + int(raw["horizon"])))
        if train_end < 1 or test_start < train_end or test_end <= test_start or test_end > len(actual):
            failures.append(f"origin {index}: invalid or overlapping train/test bounds")
            continue
        observed = actual[test_start:test_end]
        fitted = predicted[test_start:test_end]
        if baseline is None:
            reference = [actual[train_end - 1]] * len(observed)
        else:
            reference = baseline[test_start:test_end]
        rows.append({
            "origin": index,
            "train_end": train_end,
            "test_start": test_start,
            "test_end": test_end,
            "n": len(observed),
            "model_rmse": _rmse(observed, fitted),
            "baseline_rmse": _rmse(observed, reference),
            "model_mae": _mae(observed, fitted),
            "baseline_mae": _mae(observed, reference),
        })
    if not rows:
        failures.append("no valid rolling-origin holdouts")
    model_rmse = _mean([row["model_rmse"] for row in rows]) if rows else math.inf
    baseline_rmse = _mean([row["baseline_rmse"] for row in rows]) if rows else math.inf
    tolerance = float(payload.get("relative_tolerance", 0.0))
    relative_gain = (baseline_rmse - model_rmse) / max(abs(baseline_rmse), EPS)
    if rows and relative_gain < -tolerance:
        failures.append("model is worse than the ordered naive baseline")
    if any(row["test_start"] < row["train_end"] for row in rows):
        failures.append("temporal leakage detected")
    return _status(
        not failures,
        {"origins": rows, "mean_model_rmse": model_rmse, "mean_baseline_rmse": baseline_rmse,
         "relative_gain": relative_gain, "holdouts": len(rows)},
        failures,
    )


def optimization_check(payload: dict[str, Any]) -> dict[str, Any]:
    """Check bound/equality/inequality residuals and a reported optimality gap."""
    x = _numbers(payload.get("x", []), "x", 1)
    tolerance = float(payload.get("tolerance", 1e-7))
    residuals: dict[str, list[float]] = {"lower": [], "upper": [], "equality": [], "inequality": []}
    lower = payload.get("lower")
    upper = payload.get("upper")
    if lower is not None:
        values = _numbers(lower, "lower", len(x))
        if len(values) != len(x):
            raise ValueError("lower and x must have the same length")
        residuals["lower"] = [max(0.0, lo - value) for lo, value in zip(values, x)]
    if upper is not None:
        values = _numbers(upper, "upper", len(x))
        if len(values) != len(x):
            raise ValueError("upper and x must have the same length")
        residuals["upper"] = [max(0.0, value - hi) for value, hi in zip(x, values)]
    residuals["equality"] = [abs(float(value)) for value in payload.get("equality_residuals", [])]
    residuals["inequality"] = [max(0.0, float(value)) for value in payload.get("inequality_residuals", [])]
    if any(not math.isfinite(value) for values in residuals.values() for value in values):
        raise ValueError("constraint residuals must be finite")
    maximum = max((value for values in residuals.values() for value in values), default=0.0)
    objective = float(payload.get("objective_value"))
    if not math.isfinite(objective):
        raise ValueError("objective_value must be finite")
    sense = str(payload.get("sense", "min")).lower()
    if sense not in {"min", "max"}:
        raise ValueError("sense must be min or max")
    gaps: dict[str, float] = {}
    if payload.get("best_known") is not None:
        best = float(payload["best_known"])
        gaps["best_known_relative"] = abs(objective - best) / max(abs(best), 1.0)
    if payload.get("bound") is not None:
        bound = float(payload["bound"])
        signed = objective - bound if sense == "min" else bound - objective
        gaps["bound_relative"] = max(0.0, signed) / max(abs(objective), 1.0)
    gap_limit = float(payload.get("gap_tolerance", tolerance))
    gap_failures = [f"{name} exceeds gap tolerance" for name, value in gaps.items() if value > gap_limit]
    independent: dict[str, Any] = {}
    independent_failures: list[str] = []
    coefficients = payload.get("objective_coefficients")
    linear_constraints = payload.get("linear_constraints")
    if coefficients is not None:
        coefficients = _numbers(coefficients, "objective_coefficients", len(x))
        if len(coefficients) != len(x):
            raise ValueError("objective_coefficients and x must have the same length")
        recomputed_objective = sum(coefficient * value for coefficient, value in zip(coefficients, x))
        independent["recomputed_objective"] = recomputed_objective
        if abs(recomputed_objective - objective) > tolerance:
            independent_failures.append("reported objective does not match the decision vector")
    if linear_constraints is not None:
        recomputed_residuals = []
        for constraint in linear_constraints:
            lhs = _numbers(constraint.get("coefficients", []), "linear constraint coefficients", len(x))
            if len(lhs) != len(x):
                raise ValueError("linear constraint coefficients and x must have the same length")
            value = sum(coefficient * decision for coefficient, decision in zip(lhs, x))
            rhs = float(constraint["rhs"])
            constraint_sense = str(constraint["sense"])
            if constraint_sense == "<=":
                violation = max(0.0, value - rhs)
            elif constraint_sense == ">=":
                violation = max(0.0, rhs - value)
            elif constraint_sense == "==":
                violation = abs(value - rhs)
            else:
                raise ValueError("linear constraint sense must be <=, >=, or ==")
            recomputed_residuals.append({"lhs": value, "sense": constraint_sense, "rhs": rhs, "violation": violation})
        independent["recomputed_constraints"] = recomputed_residuals
        if any(row["violation"] > tolerance for row in recomputed_residuals):
            independent_failures.append("independently recomputed constraint residual exceeds tolerance")
    if payload.get("exact_binary_check"):
        if coefficients is None or linear_constraints is None:
            raise ValueError("exact_binary_check requires objective_coefficients and linear_constraints")
        if len(x) > 20:
            raise ValueError("exact binary validation supports at most twenty variables")
        optimum = None
        feasible_assignments = 0
        for mask in range(1 << len(x)):
            decision = [(mask >> index) & 1 for index in range(len(x))]
            feasible = True
            for constraint in linear_constraints:
                value = sum(float(coefficient) * selected for coefficient, selected in zip(constraint["coefficients"], decision))
                rhs = float(constraint["rhs"])
                constraint_sense = str(constraint["sense"])
                feasible = ((constraint_sense == "<=" and value <= rhs + tolerance)
                            or (constraint_sense == ">=" and value >= rhs - tolerance)
                            or (constraint_sense == "==" and abs(value - rhs) <= tolerance))
                if not feasible:
                    break
            if not feasible:
                continue
            feasible_assignments += 1
            value = sum(coefficient * selected for coefficient, selected in zip(coefficients, decision))
            optimum = value if optimum is None else (max(optimum, value) if sense == "max" else min(optimum, value))
        independent["exact_binary_optimum"] = optimum
        independent["exact_binary_feasible_assignments"] = feasible_assignments
        if optimum is None:
            independent_failures.append("exact binary check found no feasible assignment")
        elif abs(objective - optimum) > gap_limit:
            independent_failures.append("reported objective is not exact-binary optimal")
    failures = ([] if maximum <= tolerance else ["constraint residual exceeds tolerance"]) + gap_failures + independent_failures
    return _status(
        not failures,
        {"objective_value": objective, "sense": sense, "max_constraint_residual": maximum,
         "constraint_residuals": residuals, "gaps": gaps, "tolerance": tolerance,
         "gap_tolerance": gap_limit, "independent_recomputation": independent},
        failures,
    )


def _dot(left: Sequence[float], right: Sequence[float]) -> float:
    if len(left) != len(right):
        raise ValueError("state and invariant weights must have the same length")
    return sum(a * b for a, b in zip(left, right))


def ode_check(payload: dict[str, Any]) -> dict[str, Any]:
    """Check a linear invariant and convergence across step sizes."""
    states = [[float(value) for value in row] for row in payload.get("states", [])]
    if len(states) < 2 or not states[0] or any(len(row) != len(states[0]) for row in states):
        raise ValueError("states must contain at least two equal-length finite rows")
    if any(not _finite(value) for row in states for value in row):
        raise ValueError("states must be finite")
    invariant_values = payload.get("invariant_values")
    if invariant_values is None:
        weights = _numbers(payload.get("invariant_weights", []), "invariant_weights", len(states[0]))
        if len(weights) != len(states[0]):
            raise ValueError("invariant_weights and state width must match")
        invariant_values = [_dot(row, weights) for row in states]
    else:
        invariant_values = _numbers(invariant_values, "invariant_values", len(states))
        if len(invariant_values) != len(states):
            raise ValueError("invariant_values and states must have the same length")
    initial = invariant_values[0]
    scale = max(abs(initial), 1.0)
    conservation_error = max(abs(value - initial) / scale for value in invariant_values)
    runs = payload.get("step_runs") or []
    convergence_rows: list[dict[str, float]] = []
    for left, right in zip(runs, runs[1:]):
        left_state = _numbers(left["final_state"], "step final_state", 1)
        right_state = _numbers(right["final_state"], "step final_state", len(left_state))
        if len(left_state) != len(right_state):
            raise ValueError("step runs must have equal final-state widths")
        difference = max(abs(a - b) for a, b in zip(left_state, right_state))
        convergence_rows.append({"coarse_step": float(left["step"]), "fine_step": float(right["step"]),
                                 "max_difference": difference})
    nonincreasing = all(
        convergence_rows[i + 1]["max_difference"] <= convergence_rows[i]["max_difference"] * (1 + 1e-9)
        for i in range(len(convergence_rows) - 1)
    )
    tolerance = float(payload.get("tolerance", 1e-6))
    failures = []
    if conservation_error > tolerance:
        failures.append("conservation error exceeds tolerance")
    if convergence_rows and not nonincreasing:
        failures.append("step refinement does not reduce successive differences")
    return _status(
        not failures,
        {"initial_invariant": initial, "final_invariant": invariant_values[-1],
         "max_relative_conservation_error": conservation_error, "step_convergence": convergence_rows,
         "nonincreasing_difference": nonincreasing, "tolerance": tolerance},
        failures,
    )


def _lag1(values: Sequence[float]) -> float:
    if len(values) < 3:
        return 0.0
    mean = _mean(values)
    centered = [value - mean for value in values]
    denominator = sum(value * value for value in centered)
    return sum(a * b for a, b in zip(centered, centered[1:])) / denominator if denominator > EPS else 0.0


def monte_carlo_check(payload: dict[str, Any]) -> dict[str, Any]:
    """Estimate MCSE, account for lag-one autocorrelation, and inspect warm-up."""
    raw = _numbers(payload.get("samples", []), "samples", 4)
    warmup = int(payload.get("warmup", 0))
    if warmup < 0 or warmup >= len(raw) - 2:
        raise ValueError("warmup must leave at least two post-warmup samples")
    values = raw[warmup:]
    stdev = statistics.stdev(values) if len(values) > 1 else 0.0
    rho = max(-0.99, min(0.99, _lag1(values)))
    iid_mcse = stdev / math.sqrt(len(values))
    effective_n = len(values) * (1 - rho) / max(1 + rho, EPS)
    adjusted_mcse = stdev / math.sqrt(max(effective_n, 1.0))
    full_mean = _mean(raw)
    post_mean = _mean(values)
    shift = abs(post_mean - full_mean)
    scale = max(stdev, abs(post_mean), 1.0)
    warmup_limit = float(payload.get("warmup_tolerance", 0.05)) * scale
    target = float(payload.get("mcse_target", 0.05))
    relative_mcse = adjusted_mcse / max(abs(post_mean), 1.0)
    failures = []
    if relative_mcse > target:
        failures.append("adjusted MCSE exceeds target")
    if warmup and shift > warmup_limit:
        failures.append("post-warm-up mean differs materially from full-chain mean")
    batch_size = int(payload.get("batch_size", 0))
    batch_mcse = None
    if batch_size > 1 and len(values) >= 2 * batch_size:
        batches = [_mean(values[i:i + batch_size]) for i in range(0, len(values) - batch_size + 1, batch_size)]
        if len(batches) > 1:
            batch_mcse = statistics.stdev(batches) / math.sqrt(len(batches))
    return _status(
        not failures,
        {"draws": len(values), "warmup": warmup, "mean": post_mean, "stdev": stdev,
         "lag1_autocorrelation": rho, "effective_sample_size": effective_n,
         "iid_mcse": iid_mcse, "adjusted_mcse": adjusted_mcse, "relative_mcse": relative_mcse,
         "full_chain_mean": full_mean, "warmup_shift": shift, "warmup_limit": warmup_limit,
         "batch_mcse": batch_mcse, "mcse_target": target},
        failures,
    )


def _normalize_column(values: Sequence[float], direction: str) -> list[float]:
    low, high = min(values), max(values)
    if abs(high - low) <= EPS:
        return [0.5] * len(values)
    if direction == "cost":
        return [(high - value) / (high - low) for value in values]
    if direction != "benefit":
        raise ValueError("direction must be benefit or cost")
    return [(value - low) / (high - low) for value in values]


def _rank_order(scores: Sequence[float]) -> list[int]:
    return sorted(range(len(scores)), key=lambda index: (-scores[index], index))


def _kendall_tau(left: Sequence[int], right: Sequence[int]) -> float:
    positions = {item: index for index, item in enumerate(right)}
    concordant = discordant = 0
    for i, first in enumerate(left):
        for second in left[i + 1:]:
            if positions[first] < positions[second]:
                concordant += 1
            else:
                discordant += 1
    total = concordant + discordant
    return (concordant - discordant) / total if total else 1.0


def ranking_check(payload: dict[str, Any]) -> dict[str, Any]:
    """Detect top-rank and pairwise reversals under plausible weight changes."""
    matrix = [[float(value) for value in row] for row in payload.get("matrix", [])]
    if len(matrix) < 2 or not matrix[0] or any(len(row) != len(matrix[0]) for row in matrix):
        raise ValueError("matrix must contain at least two equal-width rows")
    if any(not math.isfinite(value) for row in matrix for value in row):
        raise ValueError("matrix values must be finite")
    columns = len(matrix[0])
    weights = _numbers(payload.get("weights", [1.0] * columns), "weights", columns)
    if len(weights) != columns or any(weight < 0 for weight in weights) or sum(weights) <= EPS:
        raise ValueError("weights must be nonnegative and nonzero")
    directions = list(payload.get("directions", ["benefit"] * columns))
    if len(directions) != columns:
        raise ValueError("directions and matrix width must match")
    method = str(payload.get("method", "weighted_sum")).lower()
    if method not in {"weighted_sum", "topsis"}:
        raise ValueError("ranking method must be weighted_sum or topsis")

    def score(selected_weights: list[float], selected_directions: list[str]) -> list[float]:
        normalized = [_normalize_column([row[col] for row in matrix], selected_directions[col]) for col in range(columns)]
        total = sum(selected_weights)
        normalized_weights = [weight / total for weight in selected_weights]
        weighted = [
            [normalized[col][row] * normalized_weights[col] for col in range(columns)]
            for row in range(len(matrix))
        ]
        if method == "weighted_sum":
            return [sum(row) for row in weighted]
        positive = [max(row[col] for row in weighted) for col in range(columns)]
        negative = [min(row[col] for row in weighted) for col in range(columns)]
        result = []
        for row in weighted:
            distance_positive = math.sqrt(sum((value - ideal) ** 2 for value, ideal in zip(row, positive)))
            distance_negative = math.sqrt(sum((value - anti) ** 2 for value, anti in zip(row, negative)))
            result.append(distance_negative / max(distance_positive + distance_negative, EPS))
        return result

    scores = score(weights, directions)
    baseline = _rank_order(scores)
    perturbations = payload.get("perturbations") or []
    rows = []
    failures = []
    threshold = float(payload.get("minimum_kendall", 0.8))
    for index, perturbation in enumerate(perturbations):
        varied_weights = _numbers(perturbation.get("weights", weights), "perturbation weights", columns)
        if len(varied_weights) != columns or any(weight < 0 for weight in varied_weights) or sum(varied_weights) <= EPS:
            raise ValueError("perturbation weights must be nonnegative and nonzero")
        varied_directions = list(perturbation.get("directions", directions))
        if len(varied_directions) != columns:
            raise ValueError("perturbation directions and matrix width must match")
        varied_scores = score(varied_weights, varied_directions)
        order = _rank_order(varied_scores)
        tau = _kendall_tau(baseline, order)
        top_changed = order[0] != baseline[0]
        rows.append({"perturbation": index, "rank_order": order, "top_changed": top_changed, "kendall_tau": tau})
        if top_changed or tau < threshold:
            failures.append(f"perturbation {index}: ranking is unstable")
    return _status(
        not failures,
        {"method": method, "baseline_scores": scores, "baseline_rank_order": baseline, "perturbations": rows,
         "minimum_kendall": threshold},
        failures,
    )


CHECKS = {
    "rolling_origin": rolling_origin_check,
    "optimization": optimization_check,
    "ode": ode_check,
    "monte_carlo": monte_carlo_check,
    "ranking": ranking_check,
}


def run_payload(payload: dict[str, Any]) -> dict[str, Any]:
    checks = payload.get("checks") if isinstance(payload, dict) else None
    if checks is None:
        checks = [payload]
    if not checks:
        return {"schemaVersion": 1, "checks": [], "ok": False,
                "error": "at least one validation check is required"}
    reports = []
    for index, check in enumerate(checks):
        kind = str(check.get("kind", ""))
        if kind not in CHECKS:
            entry = {"check": index, "kind": kind, "status": "failed", "ok": False,
                     "failures": [f"unknown check kind: {kind}"], "evidence": {}}
            for key in ("id", "claim_id", "subproblem_id"):
                if key in check:
                    entry[key] = check[key]
            reports.append(entry)
            continue
        try:
            report = CHECKS[kind](check)
        except (KeyError, TypeError, ValueError, ZeroDivisionError) as error:
            report = {"status": "failed", "ok": False, "failures": [str(error)], "evidence": {}}
        report_entry = {"check": index, "kind": kind, **report}
        for key in ("id", "claim_id", "subproblem_id"):
            if key in check:
                report_entry[key] = check[key]
        reports.append(report_entry)
    return {"schemaVersion": 1, "checks": reports, "ok": all(report["ok"] for report in reports)}


def self_test() -> dict[str, Any]:
    payload = {"checks": [
        {"kind": "rolling_origin", "actual": [1, 2, 3, 4, 5, 6, 7, 8],
         "predicted": [0, 2.1, 3.0, 4.1, 5.1, 6.1, 7.0, 8.1],
         "origins": [{"train_end": 3, "horizon": 2}, {"train_end": 5, "horizon": 2}]},
        {"kind": "optimization", "x": [1, 0, 1], "lower": [0, 0, 0], "upper": [1, 1, 1],
         "objective_value": 13, "best_known": 13, "sense": "max",
         "objective_coefficients": [8, 6, 5], "exact_binary_check": True,
         "linear_constraints": [{"coefficients": [4, 3, 2], "sense": "<=", "rhs": 6}]},
        {"kind": "ode", "states": [[1, 2], [0.9, 2.1], [0.8, 2.2]], "invariant_weights": [1, 1],
         "step_runs": [{"step": 0.2, "final_state": [0.8, 2.2]}, {"step": 0.1, "final_state": [0.81, 2.19]}]},
        {"kind": "monte_carlo", "samples": [10 + (i % 3) * 0.01 for i in range(40)], "warmup": 4,
         "mcse_target": 0.01},
        {"kind": "ranking", "matrix": [[9, 1], [6, 4], [2, 8]], "weights": [0.6, 0.4],
         "perturbations": [{"weights": [0.55, 0.45]}, {"weights": [0.65, 0.35]}]},
    ]}
    report = run_payload(payload)
    if not report["ok"]:
        raise AssertionError(json.dumps(report, indent=2))
    false_optimum = optimization_check({
        "x": [1, 0, 0], "objective_value": 8, "best_known": 8, "sense": "max",
        "objective_coefficients": [8, 6, 5], "exact_binary_check": True,
        "linear_constraints": [{"coefficients": [4, 3, 2], "sense": "<=", "rhs": 6}],
    })
    if false_optimum["ok"] or "reported objective is not exact-binary optimal" not in false_optimum["failures"]:
        raise AssertionError("exact binary validation accepted a false optimum")
    return report


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Run reproducible mathematical-modeling result checks")
    parser.add_argument("--input", type=Path, help="JSON file containing one check or {checks: [...]}")
    parser.add_argument("--output", type=Path, help="write report JSON to this path")
    parser.add_argument("--self-test", action="store_true", help="run built-in checks")
    args = parser.parse_args(argv)
    if args.self_test:
        report = self_test()
    elif args.input:
        report = run_payload(json.loads(args.input.read_text(encoding="utf-8")))
    else:
        parser.error("provide --input or --self-test")
    encoded = json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True)
    if args.output:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(encoded + "\n", encoding="utf-8")
    else:
        print(encoded)
    return 0 if report["ok"] else 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Lint a mathematical-modeling manuscript for traceability and overclaiming.

The checker is deliberately conservative: it reports locations for authors and
does not rewrite a manuscript. Only the Python standard library is required.
"""

from __future__ import annotations

import argparse
import json
import re
from collections import Counter
from pathlib import Path
from typing import Any


NUMBER_RE = re.compile(
    r"(?<![A-Za-z0-9_])[-+]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?(?:[eE][-+]?\d+)?%?"
)
UNIT_RE = re.compile(r"(?:\\%|%|[°µμΩA-Za-z]+(?:\s*/\s*[°µμΩA-Za-z0-9]+)?)")
CITATION_RE = re.compile(r"\\(?:cite|citep|citet|parencite)[A-Za-z*]*\s*\{([^}]*)\}")
BIB_KEY_RE = re.compile(r"@[^\s{]+\s*\{\s*([^,\s]+)", re.I)
LABEL_RE = re.compile(r"\\label\s*\{([^}]+)\}")
REF_RE = re.compile(r"\\(?:eqref|ref|pageref)\s*\{([^}]+)\}")

OVERCLAIM_TERMS = {
    "proves": "critical",
    "prove": "critical",
    "guarantees": "critical",
    "guarantee": "critical",
    "always": "major",
    "never": "major",
    "universally": "major",
    "unprecedented": "major",
    "perfectly": "major",
    "optimal": "major",
    "causal": "major",
    "generalizable": "major",
    "generalises": "major",
    "证明": "critical",
    "保证": "critical",
    "始终": "major",
    "最优": "major",
    "因果": "major",
    "普适": "major",
}
QUALIFIER_RE = re.compile(
    r"\b(?:under|within|on the declared|in the observed|simulated|conditional|for this dataset)\b"
    r"|在(?:本数据|该样本|所给|模拟|声明的|限定)条件下",
    re.I,
)
RESULT_CUE_RE = re.compile(r"result|accuracy|error|rate|increase|decrease|metric|结果|准确|误差|提升|下降|指标", re.I)


def _finding(code: str, severity: str, file: str, line: int, message: str) -> dict[str, Any]:
    return {"code": code, "severity": severity, "file": file, "line": line, "message": message}


def _number_value(token: str) -> str:
    return token.replace(",", "").rstrip("%")


def _files(root: Path) -> list[Path]:
    return sorted(
        path for path in root.rglob("*")
        if path.is_file() and path.suffix.lower() in {".tex", ".md", ".bib"}
    )


def scan(root: Path) -> dict[str, Any]:
    inventory: dict[str, Any] = {
        "numbers": [], "units": [], "citations": [], "labels": [], "references": [], "bibliography": []
    }
    findings: list[dict[str, Any]] = []
    labels: dict[str, tuple[str, int]] = {}
    refs: list[tuple[str, str, int]] = []
    bib_keys: list[tuple[str, str, int]] = []

    for path in _files(root):
        relative = path.relative_to(root).as_posix()
        try:
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            findings.append(_finding("ENCODING", "major", relative, 1, "file is not UTF-8; inventory is incomplete"))
            continue
        lines = text.splitlines()
        for line_number, line in enumerate(lines, 1):
            for match in NUMBER_RE.finditer(line):
                suffix = line[match.end(): match.end() + 24]
                # Ignore the small TeX spacing commands before a unit, while
                # retaining escaped percent signs as the percent unit.
                unit_match = UNIT_RE.match(re.sub(r"^(?:\\[,;:]|\\s)+", "", suffix.lstrip()))
                unit = unit_match.group(0) if unit_match else ("%" if match.group(0).endswith("%") else "")
                unit = unit.replace(r"\%", "%")
                record = {
                    "file": relative, "line": line_number, "token": match.group(0),
                    "value": _number_value(match.group(0)), "unit": unit,
                }
                inventory["numbers"].append(record)
                if unit:
                    inventory["units"].append({"file": relative, "line": line_number, "unit": unit})
            for match in CITATION_RE.finditer(line):
                for key in (part.strip() for part in match.group(1).split(",")):
                    if key:
                        inventory["citations"].append({"file": relative, "line": line_number, "key": key})
            for match in LABEL_RE.finditer(line):
                label = match.group(1).strip()
                inventory["labels"].append({"file": relative, "line": line_number, "key": label})
                if label in labels:
                    old_file, old_line = labels[label]
                    findings.append(_finding("DUPLICATE_LABEL", "critical", relative, line_number,
                                             f"label {label!r} already declared at {old_file}:{old_line}"))
                labels[label] = (relative, line_number)
            for match in REF_RE.finditer(line):
                for key in (part.strip() for part in match.group(1).split(",")):
                    if key:
                        refs.append((key, relative, line_number))
                        inventory["references"].append({"file": relative, "line": line_number, "key": key})
            if path.suffix.lower() in {".tex", ".md"}:
                for term, default_severity in OVERCLAIM_TERMS.items():
                    if re.search(rf"(?<!\w){re.escape(term)}(?!\w)", line, re.I):
                        severity = "minor" if QUALIFIER_RE.search(line) else default_severity
                        findings.append(_finding("OVERCLAIM", severity, relative, line_number,
                                                 f"{term!r} needs an explicit evidence boundary"))
        if path.suffix.lower() == ".bib":
            for line_number, line in enumerate(lines, 1):
                for match in BIB_KEY_RE.finditer(line):
                    key = match.group(1).strip()
                    bib_keys.append((key, relative, line_number))
                    inventory["bibliography"].append({"file": relative, "line": line_number, "key": key})

    bib_set = {key for key, _, _ in bib_keys}
    for citation in inventory["citations"]:
        if citation["key"] not in bib_set:
            findings.append(_finding("MISSING_CITATION", "critical", citation["file"], citation["line"],
                                     f"citation key {citation['key']!r} has no BibTeX record"))
    label_set = set(labels)
    for key, file, line in refs:
        if key not in label_set:
            findings.append(_finding("MISSING_LABEL", "critical", file, line, f"reference target {key!r} is undefined"))
    cited_keys = {entry["key"] for entry in inventory["citations"]}
    for key, file, line in bib_keys:
        if key not in cited_keys:
            findings.append(_finding("UNUSED_BIB", "info", file, line, f"bibliography key {key!r} is not cited"))
    return {"inventory": inventory, "findings": findings}


def compare_numbers(current: dict[str, Any], baseline: dict[str, Any]) -> list[dict[str, Any]]:
    current_by_file: dict[str, list[dict[str, Any]]] = {}
    baseline_by_file: dict[str, list[dict[str, Any]]] = {}
    for item in current["inventory"]["numbers"]:
        current_by_file.setdefault(item["file"], []).append(item)
    for item in baseline["inventory"]["numbers"]:
        baseline_by_file.setdefault(item["file"], []).append(item)
    findings: list[dict[str, Any]] = []
    for file in sorted(set(current_by_file) | set(baseline_by_file)):
        now = current_by_file.get(file, [])
        old = baseline_by_file.get(file, [])
        if len(now) != len(old):
            line = now[0]["line"] if now else 1
            findings.append(_finding("NUMERIC_COUNT_DRIFT", "major", file, line,
                                     f"baseline has {len(old)} numeric tokens; current file has {len(now)}"))
        for index, (new, previous) in enumerate(zip(now, old)):
            if (new["value"], new["unit"]) != (previous["value"], previous["unit"]):
                severity = "major" if RESULT_CUE_RE.search(" ".join([file, str(new["line"])])) else "minor"
                findings.append(_finding("NUMERIC_DRIFT", severity, file, new["line"],
                                         f"{previous['token']} {previous['unit']!r} -> {new['token']} {new['unit']!r} at token {index + 1}"))
    return findings


def lint(root: Path, baseline_root: Path | None = None) -> dict[str, Any]:
    result = scan(root)
    findings = result["findings"]
    if baseline_root is not None:
        baseline = scan(baseline_root)
        findings.extend(compare_numbers(result, baseline))
        current_citations = {entry["key"] for entry in result["inventory"]["citations"]}
        baseline_citations = {entry["key"] for entry in baseline["inventory"]["citations"]}
        if current_citations != baseline_citations:
            findings.append(_finding("CITATION_DRIFT", "major", ".", 1,
                                     f"citation key set changed: {sorted(baseline_citations)} -> {sorted(current_citations)}"))
        current_labels = {entry["key"] for entry in result["inventory"]["labels"]}
        baseline_labels = {entry["key"] for entry in baseline["inventory"]["labels"]}
        if current_labels != baseline_labels:
            findings.append(_finding("LABEL_DRIFT", "major", ".", 1,
                                     f"label set changed: {sorted(baseline_labels)} -> {sorted(current_labels)}"))
        current_refs = {entry["key"] for entry in result["inventory"]["references"]}
        baseline_refs = {entry["key"] for entry in baseline["inventory"]["references"]}
        if current_refs != baseline_refs:
            findings.append(_finding("REFERENCE_DRIFT", "major", ".", 1,
                                     f"reference target set changed: {sorted(baseline_refs)} -> {sorted(current_refs)}"))
    counts = Counter(item["severity"] for item in findings)
    decision = "FAIL" if counts["critical"] else "REVIEW" if counts["major"] else "PASS"
    result.update({
        "schema_version": 1,
        "decision": decision,
        "counts": {level: counts[level] for level in ("critical", "major", "minor", "info")},
        "findings": sorted(findings, key=lambda item: (item["file"], item["line"], item["code"])),
    })
    return result


def self_test() -> None:
    import tempfile

    with tempfile.TemporaryDirectory(prefix="mmc-lint-") as temp:
        root = Path(temp) / "current"
        baseline = Path(temp) / "baseline"
        root.mkdir()
        baseline.mkdir()
        (root / "main.tex").write_text(
            "\\section{Results}\\label{sec:r}\nAccuracy is 92.0\\%. \\cite{ok}\n\\eqref{eq:x}\n"
            "\\begin{equation} x=1 \\label{eq:x} \\end{equation}\n", encoding="utf-8"
        )
        (root / "references.bib").write_text("@article{ok, title={A}}\n", encoding="utf-8")
        result = lint(root)
        assert result["decision"] == "PASS", result
        (baseline / "main.tex").write_text(
            "\\section{Results}\\label{sec:r}\nAccuracy is 92.0\\%. \\cite{ok}\n"
            "\\begin{equation} x=1 \\label{eq:x} \\end{equation}\n", encoding="utf-8"
        )
        (baseline / "references.bib").write_text("@article{ok, title={A}}\n", encoding="utf-8")
        (root / "main.tex").write_text("Accuracy is 91.0\\%. \\cite{missing}\n\\ref{nope}\n", encoding="utf-8")
        result = lint(root, baseline)
        assert result["decision"] == "FAIL", result
        assert any(item["code"] == "LABEL_DRIFT" for item in result["findings"])
    print("paper_lint self-test: ok")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, help="manuscript directory")
    parser.add_argument("--baseline", type=Path)
    parser.add_argument("--output", type=Path)
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args(argv)
    if args.self_test:
        self_test()
        return 0
    if args.root is None:
        parser.error("--root is required unless --self-test is used")
    report = lint(args.root, args.baseline)
    payload = json.dumps(report, ensure_ascii=False, indent=2) + "\n"
    if args.output:
        args.output.write_text(payload, encoding="utf-8")
    else:
        print(payload, end="")
    return 0 if report["decision"] == "PASS" else 2 if report["decision"] == "REVIEW" else 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Deterministic, dependency-free manuscript and release-package auditor.

The auditor intentionally performs conservative static checks.  It does not
pretend to render a PDF or prove a scientific result; it verifies that the
source package is internally addressable and that declared evidence can be
located before a human performs the final visual and scientific review.

Exit codes: 0 = PASS, 1 = WARN (with no blocking finding), 2 = FAIL.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import tempfile
from pathlib import Path
from typing import Any, Iterable


SCHEMA_VERSION = "1.0"
TEXT_EXTENSIONS = {".tex", ".typ", ".md", ".txt", ".bib", ".json", ".yaml", ".yml"}
MANUSCRIPT_EXTENSIONS = {".tex", ".typ"}
GRAPHIC_EXTENSIONS = {".pdf", ".png", ".jpg", ".jpeg", ".svg", ".eps", ".webp"}
EXCLUDED_PARTS = {".git", ".omx", "node_modules", "__pycache__", ".pytest_cache"}
EXCLUDED_RELEASE_SUFFIXES = (
    ".aux",
    ".blg",
    ".fdb_latexmk",
    ".fls",
    ".lof",
    ".log",
    ".lot",
    ".out",
    ".synctex.gz",
    ".toc",
)
DOI_PATTERN = re.compile(r"^10\.\d{4,9}/[-._;()/:A-Z0-9]+$", re.IGNORECASE)


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def read_text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        return path.read_text(encoding="utf-8", errors="replace")


def line_number(text: str, offset: int) -> int:
    return text.count("\n", 0, offset) + 1


def relpath(path: Path, root: Path) -> str:
    return path.relative_to(root).as_posix()


def finding(severity: str, code: str, path: str, message: str, line: int | None = None) -> dict[str, Any]:
    item: dict[str, Any] = {"severity": severity, "code": code, "path": path, "message": message}
    if line is not None:
        item["line"] = line
    return item


def iter_files(root: Path) -> Iterable[Path]:
    for path in sorted(root.rglob("*")):
        if not path.is_file() or any(part in EXCLUDED_PARTS for part in path.parts):
            continue
        if path.name.lower().endswith(EXCLUDED_RELEASE_SUFFIXES):
            continue
        yield path


def candidate_paths(base: Path, target: str, extensions: set[str]) -> list[Path]:
    raw = target.strip().strip("\"'")
    path = Path(raw)
    options = [base / path]
    if not path.suffix:
        options.extend(base / f"{raw}{ext}" for ext in sorted(extensions))
    return options


def resolve_target(root: Path, base: Path, target: str, extensions: set[str]) -> tuple[Path | None, bool]:
    raw = target.strip().strip("\"'")
    path = Path(raw)
    if path.is_absolute() or re.match(r"^[A-Za-z]:[\\/]", raw):
        return None, True
    options = candidate_paths(base, raw, extensions)
    for option in options:
        try:
            resolved = option.resolve()
            resolved.relative_to(root.resolve())
        except (OSError, ValueError):
            return None, True
        if resolved.is_file():
            return resolved, False
    return None, False


def parse_includes(root: Path, path: Path, text: str, findings: list[dict[str, Any]]) -> None:
    patterns = [
        (r"\\(?:input|include)\s*\{([^}]+)\}", "include", TEXT_EXTENSIONS),
        (r"\\bibliography\s*\{([^}]+)\}", "bibliography", {".bib"}),
        (r"\\includegraphics(?:\[[^]]*\])?\s*\{([^}]+)\}", "graphic", GRAPHIC_EXTENSIONS),
        (r"#(?:include|read)\s*\(\s*[\"']([^\"']+)[\"']\s*\)", "include", TEXT_EXTENSIONS),
        (r"#bibliography\s*\(\s*[\"']([^\"']+)[\"']", "bibliography", {".bib"}),
        (r"(?:#)?image\s*\(\s*[\"']([^\"']+)[\"']", "graphic", GRAPHIC_EXTENSIONS),
    ]
    for pattern, kind, extensions in patterns:
        for match in re.finditer(pattern, text, flags=re.IGNORECASE):
            target = match.group(1).strip()
            line = line_number(text, match.start())
            targets = [part.strip() for part in target.split(",")] if kind == "bibliography" else [target]
            for one_target in targets:
                resolved, unsafe = resolve_target(root, path.parent, one_target, extensions)
                if unsafe:
                    findings.append(finding("FAIL", "UNSAFE_REFERENCE", relpath(path, root), f"{kind} reference escapes package or is absolute: {one_target}", line))
                elif resolved is None:
                    findings.append(finding("FAIL", "MISSING_REFERENCE", relpath(path, root), f"missing {kind} target: {one_target}", line))


def parse_bibliography(root: Path) -> tuple[set[str], set[str]]:
    keys: set[str] = set()
    for path in iter_files(root):
        if path.suffix.lower() != ".bib":
            continue
        text = read_text(path)
        keys.update(match.group(1).strip() for match in re.finditer(r"@[^,{(]+\s*[({]\s*([^,\s]+)", text))
    for path in iter_files(root):
        if path.suffix.lower() in MANUSCRIPT_EXTENSIONS:
            text = read_text(path)
            keys.update(match.group(1).strip() for match in re.finditer(r"\\bibitem\s*(?:\[[^]]+\])?\s*\{([^}]+)\}", text))
    return keys, set()


def parse_citations(text: str) -> list[tuple[str, int]]:
    found: list[tuple[str, int]] = []
    for match in re.finditer(r"\\cite[a-zA-Z*]*\s*(?:\[[^]]*\]\s*)*\{([^}]+)\}", text):
        found.extend((key.strip(), line_number(text, match.start())) for key in match.group(1).split(",") if key.strip())
    # Typst citations use @key.  Exclude email addresses and escaped TeX commands.
    for match in re.finditer(r"(?<![\\\w])@([A-Za-z][A-Za-z0-9_.:-]*)", text):
        found.append((match.group(1), line_number(text, match.start())))
    return found


def placeholder_findings(root: Path, path: Path, text: str) -> list[dict[str, Any]]:
    patterns = [
        r"\b(?:TODO|FIXME|TBD|WIP|XXX)\b",
        r"\?{3,}",
        r"\b(?:lorem\s+ipsum|your[_ -]?name|insert[_ -]?here|fill[_ -]?in)\b",
        r"\[\s*(?:待补充|未填写|占位|TODO)[^\]]*\]",
        r"<\s*(?:insert|fill|replace|todo|待补充|未填写|占位)[^>]*>",
    ]
    results: list[dict[str, Any]] = []
    for pattern in patterns:
        for match in re.finditer(pattern, text, flags=re.IGNORECASE):
            results.append(finding("FAIL", "PLACEHOLDER", relpath(path, root), f"unresolved placeholder: {match.group(0)}", line_number(text, match.start())))
    return results


def internal_path_findings(root: Path, path: Path, text: str) -> list[dict[str, Any]]:
    pattern = re.compile(r"(?:[A-Za-z]:[\\/][^\s)\]}>,;]+|(?:/Users/|/home/|/mnt/|/opt/|/tmp/)[^\s)\]}>,;]+|(?:^|[\\/])(?:desktop-app|MathModelAgent|\.agents)(?:[\\/][^\s)\]}>,;]+))", re.IGNORECASE)
    results: list[dict[str, Any]] = []
    for match in pattern.finditer(text):
        if match.group(0).startswith(("http://", "https://")):
            continue
        results.append(finding("FAIL", "INTERNAL_PATH", relpath(path, root), f"internal or machine-specific path: {match.group(0).strip()}", line_number(text, match.start())))
    return results


def section_findings(root: Path, path: Path, text: str) -> list[dict[str, Any]]:
    headings: list[str] = []
    for match in re.finditer(r"\\(?:chapter|section|subsection)\s*\{([^}]+)\}|^\s*=+\s+(.+?)\s*$", text, flags=re.IGNORECASE | re.MULTILINE):
        headings.append((match.group(1) or match.group(2)).strip().lower())
    if not headings:
        return [finding("FAIL", "NO_SECTIONS", relpath(path, root), "manuscript has no detectable section headings")]
    groups = {
        "introduction": ("introduction", "background", "引言", "背景", "问题提出", "问题重述", "问题分析"),
        "methods": ("method", "model", "methodology", "方法", "模型", "建模"),
        "results": ("result", "analysis", "experiment", "结果", "分析", "实验", "验证"),
        "conclusion": ("conclusion", "discussion", "结论", "讨论", "建议", "局限"),
    }
    results: list[dict[str, Any]] = []
    for name, tokens in groups.items():
        if not any(any(token in heading for token in tokens) for heading in headings):
            results.append(finding("WARN", "SECTION_GAP", relpath(path, root), f"no heading matched required section group: {name}"))
    return results


def parse_scalar(value: str) -> Any:
    value = value.strip()
    if not value:
        return None
    if value.startswith("{") and value.endswith("}"):
        result: dict[str, Any] = {}
        for item in value[1:-1].split(","):
            if ":" not in item:
                continue
            key, nested_value = item.split(":", 1)
            result[key.strip()] = parse_scalar(nested_value)
        return result
    if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
        return value[1:-1]
    lowered = value.lower()
    if lowered in {"true", "false"}:
        return lowered == "true"
    if lowered in {"null", "none", "~"}:
        return None
    try:
        return float(value) if any(char in value for char in ".eE") else int(value)
    except ValueError:
        return value


def parse_canonical_evidence_yaml(text: str) -> dict[str, Any] | None:
    """Parse the canonical evidence list without requiring a YAML dependency."""
    evidence: list[dict[str, Any]] = []
    current: dict[str, Any] | None = None
    source: dict[str, Any] | None = None
    in_evidence = False
    for raw in text.splitlines():
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        indent = len(raw) - len(raw.lstrip(" "))
        if indent == 0:
            if stripped == "evidence:":
                in_evidence = True
                continue
            if in_evidence:
                break
        if not in_evidence:
            continue
        if indent == 2 and stripped.startswith("-"):
            current = {}
            evidence.append(current)
            source = None
            stripped = stripped[1:].strip()
            if stripped and ":" in stripped:
                key, nested_value = stripped.split(":", 1)
                current[key.strip()] = parse_scalar(nested_value)
            continue
        if current is None or ":" not in stripped:
            continue
        key, nested_value = stripped.split(":", 1)
        key = key.strip()
        if indent == 4:
            parsed = parse_scalar(nested_value)
            if key == "source" and parsed is None:
                source = {}
                current[key] = source
            else:
                current[key] = parsed
                source = current[key] if key == "source" and isinstance(current[key], dict) else None
        elif indent >= 6 and source is not None:
            source[key] = parse_scalar(nested_value)
    return {"evidence": evidence} if evidence else None


def load_structured(path: Path) -> Any:
    if path.suffix.lower() == ".json":
        try:
            return json.loads(read_text(path))
        except (ValueError, OSError):
            return None
    return parse_canonical_evidence_yaml(read_text(path))


def iter_claim_records(value: Any) -> Iterable[dict[str, Any]]:
    if isinstance(value, dict):
        collection_keys = ("claims", "evidence")
        for collection_key in collection_keys:
            records = value.get(collection_key)
            if isinstance(records, list):
                for item in records:
                    if isinstance(item, dict):
                        yield item
        if value.get("claim_id") or (value.get("id") and any(key in value for key in ("locator", "evidence_locator", "evidence", "source"))):
            yield value
        for key, item in value.items():
            if key in collection_keys:
                continue
            yield from iter_claim_records(item)
    elif isinstance(value, list):
        for item in value:
            yield from iter_claim_records(item)


def validate_locator(root: Path, locator: str) -> tuple[bool, str]:
    value = str(locator).strip()
    if not value:
        return False, "empty locator"
    file_part, _, pointer = value.partition("#")
    line_match = re.match(r"^(.*?):(\d+)(?::(\d+))?$", file_part)
    line: int | None = None
    if line_match:
        file_part = line_match.group(1)
        line = int(line_match.group(2))
    target = (root / file_part).resolve()
    try:
        target.relative_to(root.resolve())
    except ValueError:
        return False, "locator escapes package"
    if not target.is_file():
        return False, f"file not found: {file_part}"
    if line is not None and line > len(read_text(target).splitlines()):
        return False, f"line {line} exceeds file length"
    if pointer and pointer.startswith("/") and target.suffix.lower() == ".json":
        try:
            node: Any = json.loads(read_text(target))
            for key in pointer.lstrip("/").split("/"):
                node = node[key.replace("~1", "/").replace("~0", "~")]
        except (KeyError, IndexError, TypeError, ValueError):
            return False, f"JSON pointer not found: #{pointer}"
    return True, "resolved"


def normalize_doi(value: Any) -> str:
    doi = str(value or "").strip().lower()
    doi = re.sub(r"^https?://(?:dx\.)?doi\.org/", "", doi)
    return doi.rstrip(".,; ")


def bibliography_doi_keys(root: Path) -> dict[str, set[str]]:
    result: dict[str, set[str]] = {}
    for path in iter_files(root):
        if path.suffix.lower() != ".bib":
            continue
        text = read_text(path)
        entries = list(re.finditer(r"@[^,{(]+\s*[({]\s*([^,\s]+)\s*,", text))
        for index, entry in enumerate(entries):
            end = entries[index + 1].start() if index + 1 < len(entries) else len(text)
            block = text[entry.start() : end]
            doi_match = re.search(r"\bdoi\s*=\s*[\{\"]([^}\"]+)", block, flags=re.IGNORECASE)
            if doi_match:
                result.setdefault(normalize_doi(doi_match.group(1)), set()).add(entry.group(1).strip())
    return result


def resolve_evidence_path(root: Path, raw_path: Any) -> tuple[Path | None, str]:
    value = str(raw_path or "").strip().strip("\"'")
    if not value:
        return None, "empty source path"
    path = Path(value)
    if path.is_absolute() or re.match(r"^[A-Za-z]:[\\/]", value):
        return None, "absolute source path"
    try:
        target = (root / path).resolve()
        target.relative_to(root.parent.resolve())
    except (OSError, ValueError):
        return None, "source path escapes the project work directory"
    if not target.is_file():
        return None, f"file not found: {value}"
    return target, "resolved"


def resolve_data_locator(path: Path, locator: Any) -> tuple[bool, str, Any]:
    value = str(locator or "").strip()
    if not value:
        return False, "empty data locator", None
    if path.suffix.lower() != ".json":
        return False, f"structured locator requires JSON source: {path.name}", None
    try:
        node: Any = json.loads(read_text(path))
    except (OSError, ValueError):
        return False, f"invalid JSON source: {path.name}", None
    tokens = value.lstrip("#/").split("/") if value.startswith(("#/", "/")) else value.split(".")
    try:
        for token in tokens:
            token = token.replace("~1", "/").replace("~0", "~")
            node = node[int(token)] if isinstance(node, list) else node[token]
    except (KeyError, IndexError, TypeError, ValueError):
        return False, f"data locator not found: {value}", None
    return True, "resolved", node


def numeric_value_is_used(record: dict[str, Any], manuscript_text: str) -> bool:
    value = record.get("value")
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        return False
    tolerance = record.get("tolerance", 0)
    tolerance = float(tolerance) if isinstance(tolerance, (int, float)) else 0.0
    for token in re.findall(r"(?<![A-Za-z0-9_.])-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?", manuscript_text):
        try:
            observed = float(token)
        except ValueError:
            continue
        decimals = len(token.partition(".")[2]) if "." in token else 0
        rounding_tolerance = 0.5 * 10**-decimals
        if abs(observed - float(value)) <= max(tolerance, rounding_tolerance, 1e-12):
            return True
    return False


def validate_evidence_record(root: Path, record: dict[str, Any], doi_keys: dict[str, set[str]]) -> list[dict[str, Any]]:
    claim_id = str(record.get("id") or record.get("claim_id") or "unnamed-claim")
    evidence_type = str(record.get("type") or "").strip().lower()
    source = record.get("source")
    if not isinstance(source, dict):
        legacy_locator = record.get("evidence_locator") or record.get("locator") or record.get("evidence") or source
        if isinstance(legacy_locator, str):
            ok, detail = validate_locator(root, legacy_locator)
            return [] if ok else [finding("FAIL", "INVALID_LOCATOR", ".", f"claim {claim_id}: {detail}")]
        return [finding("FAIL", "INVALID_EVIDENCE_SOURCE", ".", f"claim {claim_id} has no structured source")]
    if evidence_type == "citation" or "doi" in source:
        doi = normalize_doi(source.get("doi"))
        if not DOI_PATTERN.fullmatch(doi):
            return [finding("FAIL", "INVALID_DOI", ".", f"claim {claim_id} has an invalid DOI")]
        if doi not in doi_keys:
            return [finding("FAIL", "DOI_NOT_IN_BIBLIOGRAPHY", ".", f"claim {claim_id} DOI is absent from the packaged bibliography: {doi}")]
        return []
    target, detail = resolve_evidence_path(root, source.get("path") or source.get("file"))
    if target is None:
        return [finding("FAIL", "MISSING_EVIDENCE_SOURCE", ".", f"claim {claim_id}: {detail}")]
    locator = source.get("locator") or record.get("locator")
    if locator:
        ok, locator_detail, observed = resolve_data_locator(target, locator)
        if not ok:
            return [finding("FAIL", "INVALID_EVIDENCE_LOCATOR", ".", f"claim {claim_id}: {locator_detail}")]
        expected = record.get("value")
        if isinstance(expected, (int, float)) and not isinstance(expected, bool):
            if not isinstance(observed, (int, float)) or isinstance(observed, bool):
                return [finding("FAIL", "EVIDENCE_VALUE_TYPE", ".", f"claim {claim_id} locator does not resolve to a numeric value")]
            tolerance = float(record.get("tolerance", 0) or 0)
            if abs(float(observed) - float(expected)) > tolerance:
                return [finding("FAIL", "EVIDENCE_VALUE_MISMATCH", ".", f"claim {claim_id} expected {expected} but source contains {observed}")]
    elif evidence_type == "numeric":
        return [finding("FAIL", "MISSING_EVIDENCE_LOCATOR", ".", f"numeric claim {claim_id} has no source locator")]
    return []


def evidence_record_is_used(record: dict[str, Any], manuscript_text: str, cited: set[str], doi_keys: dict[str, set[str]]) -> bool:
    claim_id = str(record.get("id") or record.get("claim_id") or "")
    claim_text = str(record.get("claim") or "").strip()
    if claim_id and claim_id in manuscript_text:
        return True
    if claim_text and claim_text in manuscript_text:
        return True
    source = record.get("source")
    if isinstance(source, dict):
        if source.get("doi"):
            return bool(doi_keys.get(normalize_doi(source["doi"]), set()) & cited)
        raw_path = str(source.get("path") or source.get("file") or "").replace("\\", "/")
        if raw_path and (raw_path in manuscript_text or Path(raw_path).name in manuscript_text):
            return True
    return numeric_value_is_used(record, manuscript_text)


def evidence_findings(root: Path, manuscript_paths: list[Path], cited: set[str]) -> list[dict[str, Any]]:
    manifests = [path for path in iter_files(root) if path.suffix.lower() in {".json", ".yaml", ".yml"} and any(token in path.name.lower() for token in ("evidence", "claim", "result"))]
    records: list[dict[str, Any]] = []
    for path in manifests:
        data = load_structured(path)
        records.extend(iter_claim_records(data))
    if not records:
        return [finding("WARN", "NO_EVIDENCE_MANIFEST", relpath(manuscript_paths[0], root) if manuscript_paths else ".", "no claims/evidence manifest was found; central results cannot be machine-reconciled")]
    results: list[dict[str, Any]] = []
    manuscript_text = "\n".join(read_text(path) for path in manuscript_paths)
    doi_keys = bibliography_doi_keys(root)
    for index, record in enumerate(records, 1):
        claim_id = record.get("id") or record.get("claim_id") or f"claim-{index}"
        results.extend(validate_evidence_record(root, record, doi_keys))
        if not evidence_record_is_used(record, manuscript_text, cited, doi_keys):
            results.append(finding("WARN", "UNUSED_CLAIM", ".", f"claim {claim_id} is absent from manuscript source"))
    return results


def build_manifest(root: Path, exclude: set[Path]) -> dict[str, Any]:
    files: list[dict[str, Any]] = []
    for path in iter_files(root):
        if path.resolve() in exclude:
            continue
        data = path.read_bytes()
        files.append({"path": relpath(path, root), "size": len(data), "sha256": sha256_bytes(data)})
    payload = json.dumps(files, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return {"algorithm": "sha256", "files": files, "sha256": sha256_bytes(payload)}


def write_manifest(path: Path, manifest: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.suffix.lower() in {".yaml", ".yml"}:
        lines = ["schema_version: '1.0'", f"algorithm: {manifest['algorithm']}", f"sha256: {manifest['sha256']}", "files:"]
        for item in manifest["files"]:
            lines.extend([f"  - path: {json.dumps(item['path'], ensure_ascii=False)}", f"    size: {item['size']}", f"    sha256: {item['sha256']}"])
        path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    else:
        path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def render_markdown(report: dict[str, Any]) -> str:
    lines = [
        "# Paper quality audit",
        "",
        f"Decision: **{report['decision']}**",
        "",
        f"- Blocking findings: {report['counts']['fail']}",
        f"- Warnings: {report['counts']['warn']}",
        f"- Manuscripts: {report['counts']['manuscripts']}",
        f"- Manifest SHA-256: `{report['manifest']['sha256']}`",
        "",
        "## Findings",
        "",
    ]
    if report["findings"]:
        lines.extend(f"- **{item['severity']}** `{item['code']}` {item['path']}{':' + str(item['line']) if item.get('line') else ''}: {item['message']}" for item in report["findings"])
    else:
        lines.append("No findings.")
    return "\n".join(lines) + "\n"


def audit(root: Path, json_out: Path | None = None, manifest_out: Path | None = None, markdown_out: Path | None = None) -> dict[str, Any]:
    root = root.resolve()
    paths = list(iter_files(root))
    manuscript_paths = [path for path in paths if path.suffix.lower() in MANUSCRIPT_EXTENSIONS]
    findings: list[dict[str, Any]] = []
    for path in manuscript_paths:
        text = read_text(path)
        parse_includes(root, path, text, findings)
        findings.extend(placeholder_findings(root, path, text))
        findings.extend(internal_path_findings(root, path, text))
        findings.extend(section_findings(root, path, text))
    bib_keys, _ = parse_bibliography(root)
    cited: set[str] = set()
    for path in manuscript_paths:
        for key, line in parse_citations(read_text(path)):
            cited.add(key)
            if key not in bib_keys:
                findings.append(finding("FAIL", "MISSING_CITATION", relpath(path, root), f"citation key not found in bibliography: {key}", line))
    for key in sorted(bib_keys - cited):
        findings.append(finding("WARN", "UNUSED_CITATION", ".", f"bibliography entry is not cited: {key}"))
    findings.extend(evidence_findings(root, manuscript_paths, cited))
    fail_count = sum(item["severity"] == "FAIL" for item in findings)
    warn_count = sum(item["severity"] == "WARN" for item in findings)
    decision = "FAIL" if fail_count else "WARN" if warn_count else "PASS"
    excluded = {path.resolve() for path in (json_out, manifest_out, markdown_out) if path}
    manifest = build_manifest(root, excluded)
    report: dict[str, Any] = {
        "schema_version": SCHEMA_VERSION,
        "decision": decision,
        "exit_code": 2 if decision == "FAIL" else 1 if decision == "WARN" else 0,
        "root": str(root),
        "counts": {"fail": fail_count, "warn": warn_count, "manuscripts": len(manuscript_paths), "cited_keys": len(cited), "bibliography_keys": len(bib_keys)},
        "findings": findings,
        "manifest": manifest,
    }
    if json_out:
        json_out.parent.mkdir(parents=True, exist_ok=True)
        json_out.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    if manifest_out:
        write_manifest(manifest_out, manifest)
    if markdown_out:
        markdown_out.parent.mkdir(parents=True, exist_ok=True)
        markdown_out.write_text(render_markdown(report), encoding="utf-8")
    return report


def self_test() -> None:
    with tempfile.TemporaryDirectory(prefix="mmc-audit-") as temp:
        root = Path(temp)
        (root / "figures").mkdir()
        (root / "main.tex").write_text("\\section{问题重述}\n\\section{模型建立}\n\\section{结果与验证}\nAccuracy is 0.125. See \\cite{smith2024}.\\includegraphics{figures/result.pdf}\n\\section{结论}\n", encoding="utf-8")
        (root / "refs.bib").write_text("@article{smith2024, title={A test}, doi={10.1000/test-doi}}\n", encoding="utf-8")
        (root / "figures" / "result.pdf").write_bytes(b"placeholder-pdf")
        (root / "results.json").write_text(json.dumps({"metrics": {"accuracy": 0.125}}), encoding="utf-8")
        evidence_path = root / "evidence.yaml"
        canonical = """schema_version: 1
evidence:
  - id: claim:accuracy
    type: numeric
    value: 0.125
    tolerance: 0.001
    source:
      path: results.json
      locator: metrics.accuracy
  - id: claim:figure
    type: figure
    source: {path: figures/result.pdf}
  - id: claim:citation
    type: citation
    source: {doi: 10.1000/test-doi}
"""
        evidence_path.write_text(canonical, encoding="utf-8")
        report = audit(root)
        if report["decision"] != "PASS":
            raise AssertionError(report)
        manifest_path = root / "release_manifest.yaml"
        report_path = root / "paper_quality_audit.md"
        audit(root, manifest_out=manifest_path, markdown_out=report_path)
        if not manifest_path.exists() or "sha256:" not in manifest_path.read_text(encoding="utf-8") or not report_path.exists():
            raise AssertionError("report outputs were not written")
        if any(item["path"].endswith(".aux") for item in report["manifest"]["files"]):
            raise AssertionError("compile artifacts must not enter the release manifest")
        evidence_path.write_text(canonical.replace("metrics.accuracy", "metrics.missing"), encoding="utf-8")
        report = audit(root)
        if not any(item["code"] == "INVALID_EVIDENCE_LOCATOR" for item in report["findings"]):
            raise AssertionError("bad data locator was not rejected")
        evidence_path.write_text(canonical.replace("figures/result.pdf", "figures/missing.pdf"), encoding="utf-8")
        report = audit(root)
        if not any(item["code"] == "MISSING_EVIDENCE_SOURCE" for item in report["findings"]):
            raise AssertionError("missing figure evidence was not rejected")
        evidence_path.write_text(canonical.replace("10.1000/test-doi", "not-a-doi"), encoding="utf-8")
        report = audit(root)
        if not any(item["code"] == "INVALID_DOI" for item in report["findings"]):
            raise AssertionError("invalid DOI was not rejected")
        evidence_path.write_text(canonical, encoding="utf-8")
        (root / "main.tex").write_text(read_text(root / "main.tex") + "TODO", encoding="utf-8")
        report = audit(root)
        if report["decision"] != "FAIL" or report["exit_code"] != 2:
            raise AssertionError(report)
    print("SELF_TEST PASS")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("path", nargs="?", type=Path, help="release package root (positional shorthand)")
    parser.add_argument("--root", "--paper-dir", dest="root", type=Path, help="release package root")
    parser.add_argument("--json-out", type=Path, help="write the full audit report")
    parser.add_argument("--manifest-out", type=Path, help="write the SHA-256 release manifest")
    parser.add_argument("--markdown-out", type=Path, help="write a human-readable paper quality audit")
    parser.add_argument("--strict-warnings", action="store_true", help="return FAIL exit code for warnings")
    parser.add_argument("--self-test", action="store_true", help="run built-in deterministic self-test")
    args = parser.parse_args(argv)
    if args.self_test:
        self_test()
        return 0
    root = args.root or args.path
    if not root:
        parser.error("--root is required unless --self-test is used")
    report = audit(root, args.json_out, args.manifest_out, args.markdown_out)
    print(f"{report['decision']} fail={report['counts']['fail']} warn={report['counts']['warn']} files={len(report['manifest']['files'])}")
    return 2 if report["decision"] == "FAIL" or (args.strict_warnings and report["decision"] == "WARN") else 1 if report["decision"] == "WARN" else 0


if __name__ == "__main__":
    raise SystemExit(main())
